// Este nodo se ejecuta cuando llegan TODOS los items del loop
// Genera un resumen del batch procesado
const items = $input.all();
const calificados = items.filter(i => i.json.es_prospecto_real && i.json.score_final >= 60);
const top3 = calificados
  .sort((a, b) => (b.json.score_final || 0) - (a.json.score_final || 0))
  .slice(0, 3);

return [{
  json: {
    resumen: {
      total_procesados: items.length,
      total_calificados: calificados.length,
      tasa_calificacion: `${Math.round(calificados.length / items.length * 100)}%`,
      top_3_prospectos: top3.map(i => ({
        nombre: i.json.nombre,
        score: i.json.score_final,
        ubicacion: i.json.ubicacion,
        nivel: i.json.nivel_interes_b2b,
        accion: i.json.accion
      }))
    }
  }
}];
